import sys

def merge_alternate(s1: str, s2: str) -> str:
    # TODO: Merge characters alternatively and append remainder
    output = []
    i, j = 0, 0
    while i < len(s1) or j < len(s2):
        if i < len(s1):
            output.append(s1[i])
            i += 1
        if j < len(s2):
            output.append(s2[j])
            j += 1
    return "".join(output)

if __name__ == "__main__":
