    if len(parts) >= 2:
        print(merge_alternate(parts[0], parts[1]))

import sys

def solve():
    raw = sys.stdin.read().strip()
    if not raw:
        return
    nums = [int(x) for x in raw.split()]
    # TODO: Deduplicate while preserving first occurrence order
    seen = set()
    result = []
    for x in nums:
        if x not in seen:
            seen.add(x)
            result.append(x)
    print(" ".join(str(x) for x in result))

if __name__ == "__main__":
    solve()

